     7	createServer((req, res) => {
     8	  let raw = "";
     9	  req.on("data", (c) => (raw += c));
    10	  req.on("end", () => {
    11	    let body: unknown = {};
    12	    try {
    13	      body = raw ? JSON.parse(raw) : {};
    14	    } catch {
    15	      res.writeHead(400, { "content-type": "application/json" });
    16	      res.end(JSON.stringify({ error: { code: "INVALID_JSON", message: "body is not JSON" } }));
    17	      return;
    18	    }
    19	    const out = app.request(req.method ?? "GET", (req.url ?? "/").split("?")[0], body);
    20	    res.writeHead(out.status, { "content-type": "application/json" });
    21	    res.end(JSON.stringify(out.body));
    22	  });
    23	}).listen(Number(process.env.PORT ?? 3000));
