    13	
    14	interface OrderRow {
    15	  id: number;
    16	  customer: string;
    17	  amount_cents: number;
    18	  discount_cents: number;
    19	  final_amount_cents: number;
    20	  coupon_code: string | null;
    21	  status: Order["status"];
    22	  created_at: string;
    23	}
    24	
    25	const toOrder = (r: OrderRow): Order => ({
    26	  id: r.id,
    27	  customer: r.customer,
    28	  amountCents: r.amount_cents,
    29	  discountCents: r.discount_cents,
    30	  finalAmountCents: r.final_amount_cents,
    31	  couponCode: r.coupon_code,
    32	  status: r.status,
    33	  createdAt: r.created_at,
    34	});
    35	
    36	export class OrderRepository {
    37	  constructor(private readonly db: Db) {}
    38	
    39	  insert(customer: string, amountCents: number, createdAt: string): Order {
    40	    const res = this.db
    41	      .prepare(
    42	        "INSERT INTO orders (customer, amount_cents, final_amount_cents, created_at) VALUES (?, ?, ?, ?)",
    43	      )
    44	      .run(customer, amountCents, amountCents, createdAt);
    45	    return this.findById(Number(res.lastInsertRowid))!;
    46	  }
    47	
    48	  findById(id: number): Order | undefined {
    49	    const row = this.db.prepare("SELECT * FROM orders WHERE id = ?").get(id) as OrderRow | undefined;
    50	    return row && toOrder(row);
    51	  }
    52	
    53	  list(): Order[] {
    54	    return (this.db.prepare("SELECT * FROM orders ORDER BY id").all() as unknown as OrderRow[]).map(toOrder);
    55	  }
    56	
    57	  updateStatus(id: number, status: Order["status"]): void {
    58	    this.db.prepare("UPDATE orders SET status = ? WHERE id = ?").run(status, id);
    59	  }
    60	}
